def gravity(g):
    # gravity: each cell slides along (dr=+1, dc=-1) until blocked (occupied or boundary)
    h,w=len(g),len(g[0])
    o=[row[:] for row in g]; done=False
    while not done:
        moved=False
        for r in range(h):
            for c in range(w-1, -1, -1):
                if g[r][c]:
                    r2=r+1; c2=c-1
                    if r2<h and c2>=0 and not g[r2][c2]:
                        g[r2][c2]=g[r][c]; g[r][c]=0; moved=True
        if not moved: done=True
    return g

